type HasKey = { id?: string | number; name?: string | number };

const platformMap: Record<NodeJS.Platform, string> = {
  win32: "windows",
  darwin: "macos",
  linux: "linux",
  aix: "aix",
  haiku: "haiku",
  openbsd: "openbsd",
  sunos: "sunos",
  cygwin: "cygwin",
  netbsd: "netbsd",
  android: "android",
  freebsd: "freebsd",
};

function getCampaignKey(campaign: HasKey): string | null {
  const k = (campaign && (campaign.id ?? campaign.name)) ?? null;
  return k != null ? String(k) : null;
}

function tzMatchesLocation(timeZone: string, location: string) {
  if (!timeZone || !location) return false;
  const tz = timeZone.toLowerCase();
  const loc = location.toLowerCase().trim();

  if (loc === "world") return true;

  // 1. System locale-based country code check (highly accurate)
  try {
    const locale = osLocale(); // e.g., "en-US", "pt-BR", "en-IN"

    if (locale && locale.includes("-")) {
      const countryCode = locale.split("-")[1]?.toLowerCase();
      if (loc === countryCode) return true;
      if (loc === "usa" && countryCode === "us") return true;
      if (loc === "united kingdom" && countryCode === "gb") return true;
      if (loc === "uk" && countryCode === "gb") return true;
      if (loc === "brazil" && countryCode === "br") return true;
      if (loc === "india" && countryCode === "in") return true;
    }
  } catch (e) {
    // $$$$$
    // to log error getting system locale in targeting
    // console.error("[Targeting] Failed to get system locale:", e.message);
  }

  // 2. Direct check
  if (tz.includes(loc) || loc.includes(tz)) return true;

  // 3. Precise timezone city/region matching rules (fallback)
  if (loc === "usa" || loc === "us") {
    const usTzCities = [
      "new_york",
      "chicago",
      "denver",
      "los_angeles",
      "phoenix",
      "anchorage",
      "honolulu",
      "adak",
      "boise",
      "metlakatla",
      "juneau",
      "sitka",
      "yakutat",
      "nomi",
      "detroit",
      "kentucky",
      "indiana",
      "north_dakota",
    ];
    return (
      usTzCities.some((city) => tz.includes(city)) ||
      tz.includes("us/") ||
      tz.includes("hawaii") ||
      tz.includes("alaska")
    );
  }
  if (loc === "india" || loc === "in") {
    return tz === "asia/kolkata" || tz.includes("calcutta");
  }
  if (loc === "uk" || loc === "united kingdom" || loc === "gb") {
    return (
      tz.includes("london") ||
      tz.includes("europe/london") ||
      tz.includes("belfast")
    );
  }
  if (loc === "brazil" || loc === "br") {
    const brTzs = [
      "sao_paulo",
      "rio_branco",
      "fortaleza",
      "recife",
      "manaus",
      "belem",
      "noronha",
      "bahia",
      "cuiaba",
      "porto_velho",
      "boa_vista",
      "campo_grande",
      "maceio",
      "araguaina",
      "santarem",
      "eirunepe",
    ];
    return brTzs.some((city) => tz.includes(city));
  }

  return false;
}

async function checkLocationForNotification(
  location: string,
  timezone: string,
) {
  return tzMatchesLocation(timezone, location);
}

function getMatchedCountries(
  config: unionConfigsType,
  userLang: string,
  timeZone: string,
): any {
  let worldFallback = null;
  for (const country of config.country || []) {
    // Commented out userlang based check as requested
    /*
    const langMatch = (country.language || []).some((lang) =>
      userLang.toLowerCase().startsWith(lang.toLowerCase().split("_")[0])
    );

    if (!langMatch) continue;
    */

    if (country.location === "world") {
      worldFallback = country;
      continue;
    }

    if (tzMatchesLocation(timeZone, country.location)) {
      return [country];
    }
  }
  return worldFallback ? [worldFallback] : [];
}

function isRemoteUrl(u: string) {
  return typeof u === "string" && /^https?:\/\//i.test(u);
}

function getAppDataPath(): string {
  switch (process.platform) {
    case "win32":
      // Returns: C:\Users\<Username>\AppData\Roaming
      return (
        process.env.DIRPATH || path.join(os.homedir(), "AppData", "Roaming")
      );
    case "darwin":
      // Returns: /Users/<Username>/Library/Application Support
      return (
        process.env.DIRPATH ||
        path.join(os.homedir(), "Library", "Application Support")
      );
    case "linux":
      // Returns: /home/<Username>/.local/share
      return process.env.DIRPATH || path.join(os.homedir(), ".local", "share");
    default:
      throw new Error(`Unsupported platform: ${process.platform}`);
  }
}

function getAssetsDir(type: string) {
  return path.join(getAppDataPath(), "user-assets", type, "assets");
}

function collectCampaignKeys(config: unionConfigsType) {
  const keys = new Set();
  for (const country of config.country || []) {
    for (const campaignGroup of country.payload || []) {
      if (!Array.isArray(campaignGroup)) continue;
      for (const campaign of campaignGroup) {
        const key = getCampaignKey(campaign);
        if (key) keys.add(key);
      }
    }
  }
  return keys;
}

async function downloadFile(
  url: string,
  directory: string,
  fileName: string,
  force = false,
) {
  try {
    // Skip re-download only if not forcing and the file is already present.
    if (!force) {
      try {
        await fs.access(path.join(directory, fileName));
        return true;
      } catch {}
    }

    // $$$$$
    // to log remote file download URL and destination
    // console.log(`[Asset Downloader] Downloading remote file: ${url} -> ${directory}/${fileName}`);

    const downloader = new Downloader({
      url,
      directory,
      fileName,
      cloneFiles: false,
      maxAttempts: 1, // retry transient network failures
    });

    const { filePath } = await downloader.download();

    // $$$$$
    // to log completed asset download filepath
    // console.log(`[Asset Downloaded] ${filePath}`);

    return true;
  } catch (err) {
    // $$$$$
    // to log asset download error details
    // console.error("[Asset Download Error]", url, err.message);

    return false;
  }
}

async function pruneAssets(config: unionConfigsType, type: string) {
  const assetsDir = getAssetsDir(type);
  const valid = collectCampaignKeys(config);

  let entries;
  try {
    entries = await fs.readdir(assetsDir, { withFileTypes: true });
  } catch {
    return []; // assets dir doesn't exist yet, nothing to prune
  }

  const pruned = [];
  for (const entry of entries) {
    if (entry.isDirectory() && !valid.has(entry.name)) {
      await fs.rm(path.join(assetsDir, entry.name), {
        recursive: true,
        force: true,
      });
      // $$$$$
      // to log pruned old asset directory
      // console.log(`[Asset Pruned] ${type}/${entry.name}`);
      pruned.push(entry.name);
    }
  }
  return pruned;
}

