async function downloadAssets(
  config: unionConfigsType,
  type: string,
  force = false,
) {
  const assetsDir = getAssetsDir(type);

  // $$$$$
  // to log downloading assets directory path and type
  // console.log(`[Assets] Downloading ${type} assets to dir:`, assetsDir);
  let ok = true;
  let campaignDir: null | string = null;

  // In dev-mode, always force re-download of assets
  const shouldForce = true;
  // || config["dev-mode"] === true;

  const userLang = osLocale();
  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const targetCountries = getMatchedCountries(config, userLang, timeZone);

  for (const country of targetCountries) {
    for (const campaignGroup of country.payload || []) {
      if (!Array.isArray(campaignGroup)) continue;
      for (const campaign of campaignGroup) {
        // if(!matchesPlatform(campaign,process.platform))continue;

        const key = getCampaignKey(campaign);
        if (!key) continue;

        campaignDir = path.join(assetsDir, String(key));

        const files = [
          ...(campaign.css || []),
          ...(campaign.js || []),
          ...(campaign.assets || []),
          // ...(campaign.images || []),
          ...(campaign.html || []),
        ];

        if (shouldForce) {
          try {
            await fs.rm(campaignDir, { recursive: true, force: true });
            // $$$$$
            // to log cleaning campaign directory for old assets
            // console.log(`[Assets] Cleaned campaign dir to remove old assets: ${campaignDir}`);
          } catch (rmErr) {
            // $$$$$
            // to log error cleaning campaign directory
            // console.error(`[Assets] Failed to clean campaign dir ${campaignDir}:`, rmErr.message);
          }
        }

        for (const fileUrl of files) {
          if (!isRemoteUrl(fileUrl)) continue;

          const fileName = path.basename(new URL(fileUrl).pathname);

          const success = await downloadFile(
            fileUrl,
            campaignDir,
            fileName,
            shouldForce,
          );
          if (!success) ok = false;
        }
      }
    }
  }

  return { ok, campaignDir };
}

function getCachedFile(filename: string): string | null {
  try {
    const userDataPath = getAppDataPath();
    const cacheDir = path.join(userDataPath, "user-assets");
    const onboardingAssetsDir = path.join(cacheDir, filename, "assets");

    const baseJsonPath = path.join(cacheDir, "base.json");
    if (existsSync(baseJsonPath)) {
      const baseData = JSON.parse(readFileSync(baseJsonPath, "utf8"));
      const baseConfig = baseData[filename];

      const platform = platformMap[process.platform] || process.platform;
      const appVersion = (pkg as any)["version"] || "1.0.0";

      // const platformEntry = baseConfig["signing-mode"].find(
      //   (entry) =>
      //     entry.type === platform && entry["app-version"] === appVersion,
      // );
    }

    if (!existsSync(onboardingAssetsDir)) return null;

    const subdirs = readdirSync(onboardingAssetsDir, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name);

    if (subdirs.length === 0) return null;

    // The subdirectory name is the campaign ID itself
    const campaignId = String(
      subdirs[Math.floor(Math.random() * subdirs.length)],
    );

    // Check if the campaign is currently active by reading onboarding.json from cache

    let cacheFile = path.join(cacheDir, filename, `${filename}.json`);

    // if (!existsSync(cacheFile)) {
    //   cacheFile = path.resolve(
    //     __dirname,
    //     "../../renderer/src/app/core/onboarding/onboarding.json",
    //   );
    // }

    // $$$$$
    // to log resolved onboarding cacheFile path
    // console.log(`[WC debug] cacheFile resolved to: ${cacheFile}`);
    // $$$$$
    // to log existence check for onboarding cacheFile
    // console.log(`[WC debug] cacheFile exists? ${existsSync(cacheFile)}`);

    if (existsSync(cacheFile)) {
      const data = readFileSync(cacheFile, "utf8");
      const config = JSON.parse(data);

      let campaign = null;

      const userLang = osLocale();
      const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const targetCountries = getMatchedCountries(config, userLang, timeZone);

      for (const country of targetCountries || []) {
        for (const group of country.payload || []) {
          if (!Array.isArray(group)) continue;

          for (const item of group) {
            const currentPlatform =
              platformMap[process.platform] || process.platform;

            if (!item.platforms.includes(currentPlatform)) continue;

            const key = item.id || item.name;
            if (key && String(key) === campaignId) {
              campaign = item;

              break;
            }
          }
          if (campaign) break;
        }
        if (campaign) break;
      }

      if (campaign) {
        const now = Math.floor(Date.now() / 1000);
        const start = campaign.start_time ? Number(campaign.start_time) : 0;
        const end = campaign.end_time ? Number(campaign.end_time) : Infinity;

        // $$$$$
        // to log campaign start_time and formatted date
        // console.log(
        //   `[WC debug] campaign start_time: ${start} (${new Date(start * 1000).toLocaleString()})`,
        // );
        // $$$$$
        // to log campaign end_time and formatted date
        // console.log(
        //   `[WC debug] campaign end_time: ${end} (${new Date(end * 1000).toLocaleString()})`,
        // );
        // $$$$$
        // to log current timestamp and formatted date
        // console.log(
        //   `[WC debug] current time (now): ${now} (${new Date(now * 1000).toLocaleString()})`,
        // );

        const isActive = now >= start && now <= end;
        // $$$$$
        // to log campaign active status check result
        // console.log(`[WC debug] campaign isActive? ${isActive}`);
        if (!isActive) {
          // $$$$$
          // to log expired or inactive campaign fallback notice
          // console.log(
          //   `[WC] Onboarding campaign "${campaignId}" has expired or is inactive. Falling back to default UI.`,
          // );
          return null;
        }
      }
    }

    const indexPath = path.join(onboardingAssetsDir, campaignId);

    if (existsSync(indexPath)) {
      return indexPath;
    }
  } catch (err) {
    console.log(err, "error hai");
    // $$$$$
    // to log error checking onboarding folder expiration
    // console.error(
    //   "[WC] Failed to check onboarding folder expiration:",
    //   err.message,
    // );
  }

  return null;
}

async function getCachedNotificationFile(): Promise<string | null> {
  const cacheDir = path.join(getAppDataPath(), "user-assets");
  const assetsDir = path.join(cacheDir, "notification", "assets");
  const configPath = path.join(cacheDir, "notification", "notification.json");

  if (!existsSync(assetsDir) || !existsSync(configPath)) return null;

  try {
    const config = JSON.parse(
      readFileSync(configPath, "utf8"),
    ) as notificationJsonType;
    const frequencyState =
      ((await loadCacheJson("notification-frequency.json")) as Record<
        string,
        number
      > | null) ?? {};
    const timeArrayState =
      ((await loadCacheJson("notification-timearray-shown.json")) as Record<
        string,
        number[]
      > | null) ?? {};
    const platformMap: Partial<Record<NodeJS.Platform, string>> = {
      win32: "windows",
      darwin: "macos",
      linux: "linux",
    };
    const currentPlatform = platformMap[process.platform] || process.platform;
    const now = Math.floor(Date.now() / 1000);
    const userLang = Intl.DateTimeFormat().resolvedOptions().locale;
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const candidates: Array<{
      path: string;
      key: string;
      schedule: "frequency" | "time_array" | "none";
      scheduledTime?: number;
    }> = [];

    for (const country of getMatchedCountries(config, userLang, timeZone)) {
      for (const group of country.payload || []) {
        if (!Array.isArray(group)) continue;

        for (const campaign of group) {
          if (!campaign.platforms?.includes(currentPlatform)) continue;

          const start = campaign.start_time ? Number(campaign.start_time) : 0;
          const end = campaign.end_time
            ? Number(campaign.end_time)
            : Number.POSITIVE_INFINITY;
          if (
            !Number.isFinite(start) ||
            (campaign.end_time && !Number.isFinite(end)) ||
            now < start ||
            now > end
          ) {
            continue;
          }

          const campaignKey = getCampaignKey(campaign);
          if (!campaignKey) continue;

          const campaignPath = path.join(assetsDir, campaignKey);
          if (!existsSync(campaignPath)) continue;

          if (
            Array.isArray(campaign.time_array) &&
            campaign.time_array.length > 0
          ) {
            const shownTimes = timeArrayState[campaignKey] ?? [];
            const scheduledTime = campaign.time_array
              .map((value: string) => Number(value))
              .find(
                (time: number) =>
                  Number.isFinite(time) &&
                  now >= time &&
                  now - time <= 60 &&
                  !shownTimes.includes(time),
              );

            if (scheduledTime === undefined) continue;
            candidates.push({
              path: campaignPath,
              key: campaignKey,
              schedule: "time_array",
              scheduledTime,
            });
            continue;
          }

          if (campaign.frequency !== undefined) {
            const frequency = Number(campaign.frequency);
            if (!Number.isFinite(frequency) || frequency <= 0) continue;

            const lastShown = frequencyState[campaignKey];
            const intervalSeconds = (24 * 60 * 60) / frequency;

            if (
              lastShown !== undefined &&
              Number.isFinite(lastShown) &&
              now - lastShown < intervalSeconds
            ) {
              continue;
            }

            candidates.push({
              path: campaignPath,
              key: campaignKey,
              schedule: "frequency",
            });
            continue;
          }

          candidates.push({
            path: campaignPath,
            key: campaignKey,
            schedule: "none",
          });
        }
      }
    }

    if (candidates.length === 0) return null;

    const selected = candidates[Math.floor(Math.random() * candidates.length)];
    if (!selected) return null;

    if (selected.schedule === "frequency") {
      frequencyState[selected.key] = now;
      await saveCacheJson("notification-frequency.json", frequencyState);
    } else if (
      selected.schedule === "time_array" &&
      selected.scheduledTime !== undefined
    ) {
      const shownTimes = timeArrayState[selected.key] ?? [];
      shownTimes.push(selected.scheduledTime);
      timeArrayState[selected.key] = shownTimes;
      await saveCacheJson("notification-timearray-shown.json", timeArrayState);
    }

    return selected.path;
  } catch (error) {
    console.error(
      "[Notification] Failed to select cached notification:",
      error,
    );
    return null;
  }
}

